// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;
    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
        vm.warp(1000);
    }
    function testFuzz_property(uint256 depositAmt, uint256 configAmt, uint256 dt) public {
        depositAmt = bound(depositAmt, 1, 1e18);
        configAmt = bound(configAmt, 1, 1e18);
        dt = bound(dt, 1, 1e18);
        vm.assume(depositAmt != configAmt);

        TokenRecorder tok = new TokenRecorder();

        // configure governance so a deposit of depositAmt is taken from the caller
        c.configureFlashGovernance(address(tok), depositAmt, dt, false);

        // deposit via the DAO entry point (configured == false so this is admissible)
        vm.prank(c.DAO());
        c.assertGovernanceApproved(address(this), address(this), true);

        // reconfigure the global flash governance amount BEFORE withdrawal
        c.configureFlashGovernance(address(tok), configAmt, dt, false);

        // pass the pending unlock time so the withdrawal is permitted
        vm.warp(block.timestamp + dt + 1);

        vm.prank(address(this));
        c.withdrawGovernanceAsset(address(this), address(tok));

        // General rule: what c pays back on withdrawal equals what it took in
        // as that caller's flash-governance deposit (the pending decision amount),
        // independent of any later reconfiguration of flashGovernanceConfig.
        assertTrue(tok.recordedOut() == tok.recordedIn());
    }
}

contract TokenRecorder {
    uint256 public recordedIn;
    uint256 public recordedOut;

    function transferFrom(address, address, uint256 amount) external returns (bool) {
        recordedIn = amount;
        return true;
    }

    function transfer(address, uint256 amount) external returns (bool) {
        recordedOut = amount;
        return true;
    }

    function balanceOf(address) external pure returns (uint256) {
        return 0;
    }

    function allowance(address, address) external pure returns (uint256) {
        return type(uint256).max;
    }

    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    receive() external payable {}
    fallback() external payable {}
}

